using namespace InvocationTestFixture
using namespace InvocationTestFixture.Arguments

# Do not use '$retval =' or '$null =' for method invocations. They will be auto-generated.
$template = {
    param($methodProvider)

    $ErrorActionPreference = 'Continue'

    $a1, $a2, $a3 = [ArgumentProvider]::Create([ClassArg], [StructArg], [EnumArg])
    $methodProvider.SimpleParam($a1, $a2, $a3)

    $methodProvider.ParamsArray_Class()

    $methodProvider.ParamsArray_Class(@())

    $methodProvider.ParamsArray_Class($null)

    $a1, $null = [ArgumentProvider]::Create([ClassArg])
    $methodProvider.ParamsArray_Class($a1)

    $a1, $a2 = [ArgumentProvider]::Create([ClassArg], 2)
    $methodProvider.ParamsArray_Class($a1, $a2)

    $a1, $null = [ArgumentProvider]::Create([ClassArg])
    $methodProvider.ParamsArray_Class(@($a1))

    $a1, $a2 = [ArgumentProvider]::Create([ClassArg], 2)
    $methodProvider.ParamsArray_Class(@($a1, $a2))

    $a1, $a2 = [ArgumentProvider]::Create([StructArg], 2)
    $methodProvider.ByRef_Mutate([ref]$a1, [ref]$a2)
}

$generatedScriptPath = "$PSScriptRoot/RunMethodProvider.g.ps1"

function SourceGen {

    if ((Get-ItemPropertyValue -LiteralPath $PSCommandPath -Name LastWriteTime) -lt
        (Get-ItemPropertyValue -LiteralPath $generatedScriptPath -Name LastWriteTime -ErrorAction Ignore)) {
        return
    }

    $header = @'
# Copyright (c) Matthias Wolf, Mawosoft.

# <auto-generated />

using namespace InvocationTestFixture
using namespace InvocationTestFixture.Arguments

'@
    $script1 = [InvocationTransformer]::Transform($template.Ast)
    $script2 = [InvocationTransformer]::TransformWithReflection($template.Ast)
    @(
        $header
        ('function RunMethodProvider ' + $script1)
        ''
        ('function RunMethodProviderWithReflection ' + $script2)
    ) | Set-Content -LiteralPath $generatedScriptPath
}

SourceGen

. $generatedScriptPath

Remove-Variable 'template'
Remove-Variable 'generatedScriptPath'
